\label{def:cdf}


A function $F \colon \mathbb{R} \to \mathbb{R}$ is a
\emph{cumulative distribution function} (c.d.f.) if
\begin{enumerate}
\item[(i)] $x \mapsto F(x)$ is increasing;
\item[(ii)] $x \mapsto F(x)$ is right-continuous;
\item[(iii)] $\lim_{x \to -\infty} F(x) = 0$ and $\lim_{x \to +\infty} F(x) = 1$.
\end{enumerate}

\label{lem:cdf-of-random-var}



If $X$ is a real-valued random variable, then the function
$F \colon \mathbb{R} \to \mathbb{R}$ given by $F(x) = \mathsf{P} \big[ X \le x \big]$ is a c.d.f.

\label{lem:degenerate-cdf-iff-exists-jump}



$F$ is a degenerate c.d.f. if and only if there exists a $x_0 \in \mathbb{R}$ such that
\begin{align*}
F(x) = \begin{cases}
        0 & \text{ for } x < x_0 \\
        1 & \text{ for } x \ge x_0 .
       \end{cases}
\end{align*}

\begin{align*}
  F(x) = \begin{cases}
          0 & \text{ for } x < x_0 \\
          1 & \text{ for } x \ge x_0 .
         \end{cases}
  \end{align*}

\label{lem:degenerate-cdf-is-delta}



If a c.d.f. $F$ is degenerate, then it is the c.d.f. of a Dirac delta mass $\delta_{x_0}$
at some point $x_0 \in \mathbb{R}$.

\begin{align*}
  \mathsf{P}\big[ \max (X, Y) \le x \big]
  \; = \; \mathsf{P}\big[ X \le x \, \; Y \le x \big]
  \; = \; \mathsf{P}\big[ X \le x \big] \; \mathsf{P}\big[ Y \le x \big]
  \; = \; F(x) \, G(x) .
  \end{align*}

\label{lem:cdf-of-affine-max-many}


Let $X_0, X_1, \ldots, X_{n-1}$ be independent identically distributed real-valued random variables
with cumulative distribution functions $F$,
i.e. $F(x) = \mathsf{P} \big[ X_j \le x \big]$ for every $j$,
and let $a > 0$ and $b \in \mathbb{R}$.
Then the c.d.f. of
\begin{align*}
\hat{M}_n = \frac{\max_{0 \le j < n} X_j - b}{a}
\end{align*}
is the function $x \mapsto \big(F(a x + b)\big)^n$.

\begin{align*}
  \hat{M}_n = \frac{\max_{0 \le j < n} X_j - b}{a}
  \end{align*}

\label{def:oriented-affine-isomorphism}


The collection of all transformations $\mathbb{R} \to \mathbb{R}$ of the form
$x \mapsto a x + b$, where $a>0$, $b \in \mathbb{R}$, forms a group.
We call this the \emph{orientation preserving affine isomorphism group}
and denote it by $\mathrm{Aff}^+_{\mathbb{R}}$.



A c.d.f. is always continuous from the right.

Continuity of $F$ from the left at $x$ means that for any
sequence $(x_n)_{n \in \mathbb{N}}$ increasing to $x$
(i.e., $x_n \le x_{n+1} < x$ for all $n \in \mathbb{N}$)
\begin{align*}
  F(x_n) \to F(x) ,
\end{align*}
or equivalently in terms of measures
\begin{align*}
  \mu \big[ (-\infty,x_n] \big] \to \mu \big[ (-\infty,x] \big] .
\end{align*}
But by monotone convergence of measures, we always have
\begin{align*}
  \mu \big[ (-\infty,x_n] \big]
  \to \; & \mu \big[ (-\infty,x) \big] \\
  = \; & \mu \big[ (-\infty,x] \big] - \mu[\set{x}] .
\end{align*}
A comparison of these conditions shows that $F$ is also continuous from the left
at $x$ if and only if $\mu[\set{x}] = 0$.

\begin{align*}
    F(x_n) \to F(x) ,
  \end{align*}

\begin{align*}
    \mu \big[ (-\infty,x_n] \big] \to \mu \big[ (-\infty,x] \big] .
  \end{align*}

\begin{align*}
    \mu \big[ (-\infty,x_n] \big]
    \to \; & \mu \big[ (-\infty,x) \big] \\
    = \; & \mu \big[ (-\infty,x] \big] - \mu[\set{x}] .
  \end{align*}

