\label{lem:modify-limit-taylor}


Let $S \subset \mathbb{R}$ be a subset with $0 \in S$, and let $f_1, f_2 \colon S \to \mathbb{R}$ be
functions. Let also $(t_n)_{n \in \mathbb{N}}$ be a sequence in $S$,
and let $(m_n)_{n \in \mathbb{R}}$ be a sequence of real numbers tending to infinity,
$\lim_{n \to \infty} m_n = +\infty$.
Assume that for $j = 1,2$
\begin{itemize}
  \item $f_j(0)=0$;
  \item the derivative $f_j'(0)$ exists (derivative taken within the set $S$)
\end{itemize}
Assume further about $j = 1$ that
\begin{itemize}
  \item $f_1'(0) \ne 0$;
  \item the limit $\lim_{n \to \infty} \big( m_n \, f_1 (t_n) \big)$ exists;
  \item for any $\delta > 0$ there exists an $\varepsilon > 0$ such that
    if $|f_1(t)| < \varepsilon$ (with $t \in S$) then $|t| < \delta$.
\end{itemize}
Denote $c = \frac{1}{f_1'(0)} \, \lim_{n \to \infty} \big( m_n \, f_1 (t_n) \big)$.
Then we have $\lim_{n \to 0} t_n = 0$ and
\begin{align*}
  \lim_{n \to \infty} \Big( m_n \, f_2 (t_n) \Big) \; = \; & c \, f_2'(0) .
\end{align*}

\begin{align*}
    \lim_{n \to \infty} \Big( m_n \, f_2 (t_n) \Big) \; = \; & c \, f_2'(0) .
  \end{align*}

\label{lem:taylored-ev-limit}



Let $F$ and $G$ be c.d.f.s, and $(A_n)_{n \in \mathbb{N}}$ a sequence of orientation
